function validate(value){if(!value||![2,3,4].includes(value.version)||!['button','blinds'].includes(value.rule))throw new Error('Contexto inválido.');const out={version:value.version,rule:value.rule};for(const key of ['hands','calibrationHands','unassisted','correct','preflopHands','vpip','pfr','postflopActions','aggression','omahaHands']){const v=value[key];if(!Number.isInteger(v)||v<0||v>100000)throw new Error('Contagem inválida.');out[key]=v;}
 if(out.calibrationHands>10||out.correct>out.unassisted||out.vpip>out.preflopHands||out.pfr>out.vpip||out.aggression>out.postflopActions||out.preflopHands>out.hands)throw new Error('Contagens inconsistentes.');
 if(!Array.isArray(value.themes)||value.themes.length!==4)throw new Error('Temas inválidos.');out.themes=[];const seen=new Set();for(const g of value.themes){if(!THEMES[g.key]||seen.has(g.key)||!Number.isInteger(g.opportunities)||!Number.isInteger(g.misses)||g.misses<0||g.opportunities<g.misses||g.opportunities>out.unassisted)throw new Error('Tema inválido.');seen.add(g.key);const evidence=[];for(const e of (g.evidence||[]).slice(0,3)){if(!Number.isInteger(e.hand)||e.hand<1||!Number.isInteger(e.street)||e.street<0||e.street>3||!['UTG','UTG+1','UTG+2','MP+1','LJ','MP','HJ','CO','BTN','SB','BB'].includes(e.position)||!['fold','call','raise','check'].includes(e.action)||!['fold','call','raise','check'].includes(e.expected))throw new Error('Evidência inválida.');evidence.push({hand:e.hand,street:e.street,position:e.position,action:e.action,expected:e.expected});}out.themes.push({key:g.key,opportunities:g.opportunities,misses:g.misses,evidence});}if(!Array.isArray(value.opponents)||value.opponents.length!==(value.version===4?8:5))throw new Error('Adversários inválidos.');const seats=new Set();out.opponents=value.opponents.map(p=>{if(!Number.isInteger(p.seat)||p.seat<1||p.seat>(value.version===4?8:5)||seats.has(p.seat))throw new Error('Assento inválido.');seats.add(p.seat);const row={seat:p.seat};for(const key of ['bets','checks','calls','folds']){if(!Number.isInteger(p[key])||p[key]<0||p[key]>100000)throw new Error('Contagem inválida.');row[key]=p[key];}return row;});return out;
}
function study(table,key){const r=summarize(table),g=r.groups.find(g=>g.key===key);return g?.examples.length?[...g.examples].reverse():[];}
